CREATE TABLE playoff_bracket_challenges (id text PRIMARY KEY, owner_user_id text NOT NULL, name text NOT NULL, sport text NOT NULL, season_year integer NOT NULL, status text NOT NULL DEFAULT 'open', is_test_mode boolean NOT NULL DEFAULT false, config jsonb, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE playoff_bracket_entries (id text PRIMARY KEY,challenge_id text NOT NULL REFERENCES playoff_bracket_challenges(id),user_id text NOT NULL,name text NOT NULL,finalized_at timestamp,tiebreaker_total_score integer,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE playoff_bracket_series (id text PRIMARY KEY,challenge_id text NOT NULL REFERENCES playoff_bracket_challenges(id),round text NOT NULL,round_index integer NOT NULL,series_number integer NOT NULL,conference text NOT NULL,home_seed integer NOT NULL,away_seed integer NOT NULL,home_team_name text NOT NULL,away_team_name text NOT NULL,winner_team_name text,best_of integer NOT NULL DEFAULT 7,status text NOT NULL DEFAULT 'scheduled',starts_at timestamp,home_team_wins integer NOT NULL DEFAULT 0,away_team_wins integer NOT NULL DEFAULT 0,series_summary text,next_game_at timestamp,venue text,broadcast_network text,live_home_score integer,live_away_score integer,live_status text,provider_games_json jsonb,last_synced_at timestamp,next_series_number integer,next_series_slot text,source_series_home integer,source_series_away integer,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(challenge_id,series_number));
CREATE TABLE playoff_bracket_picks (id text PRIMARY KEY,challenge_id text NOT NULL REFERENCES playoff_bracket_challenges(id),entry_id text NOT NULL REFERENCES playoff_bracket_entries(id),series_id text NOT NULL REFERENCES playoff_bracket_series(id),pick_team_name text NOT NULL,confirmed_at timestamp,draft_team_name text,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(entry_id,series_id));
